      { id: 313, desc: "Distingue rasgos comunes en objetos/fenómenos (abstracción)." },
      { id: 314, desc: "Explica o comprende el significado de una metáfora." },
    ].map((item) => (
      <tr key={item.id}>
        <td>{item.desc}</td>
        {[1, 2, 3, 4, 0].map((valor) => (
          <td className="text-center" key={valor}>
            <input
              type="radio"
              name={`cognitiva-${item.id}`}
              checked={valoresCognitivas[item.id] === valor}
              onChange={() =>
                setValoresCognitivas((prev) => ({ ...prev, [item.id]: valor }))
              }
            />
          </td>
        ))}
      </tr>
    ))}
  </tbody>
</table>

